<script setup lang="ts">import { onMounted, ref } from 'vue'; import AppShell from '@/layouts/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import PanelCard from '@/components/PanelCard.vue'; import StatusPill from '@/components/StatusPill.vue'; import TwoStepWizard from '@/components/TwoStepWizard.vue'; import { connect } from '@/services/connect'; import { useSessionStore } from '@/stores/session'; import type { SecurityState } from '@/types/domain'; const state=ref<SecurityState|null>(null),wizard=ref(false),session=useSessionStore(); async function load(){state.value=await connect.security().catch(()=>null); if(state.value?.enrollmentRequired) wizard.value=true}; async function done(){await session.refresh();await load()}; onMounted(load)</script>
<template><AppShell><PageHeader title="Segurança da conta" description="Proteja seu acesso e mantenha sua conta segura."/><div class="security-grid" v-if="state"><PanelCard title="Proteção da conta"><div class="security-status-grid"><div><span>Verificação em duas etapas</span><StatusPill :status="state.enabled?'ok':'attention'" :label="state.enabled?'Ativada':'Desativada'"/></div><div><span>Recuperação</span><strong>{{state.recoveryRemaining}} códigos disponíveis</strong></div><div><span>Política</span><strong>{{state.required?'Obrigatória':'Opcional'}}</strong></div></div><button v-if="!state.enabled" class="btn primary top-gap" @click="wizard=true">Ativar proteção</button></PanelCard><PanelCard title="Senha" description="Altere sua senha periodicamente e evite reutilizá-la em outros serviços."><RouterLink class="btn ghost" to="/configuracoes">Gerenciar senha</RouterLink></PanelCard></div><TwoStepWizard :open="wizard" :required="Boolean(state?.enrollmentRequired)" @close="wizard=false" @complete="done"/></AppShell></template>
